mapper.select:


    and o.inbound_order_no like concat('%', #{inboundOrderNo}, '%')
    and o.inbound_type = #{inboundType}
    and o.source_no like concat('%', #{sourceNo}, '%')
    and o.supplier_name like concat('%', #{supplierName}, '%')
    and o.warehouse_id = #{warehouseId}
    and o.order_status = #{orderStatus}
    and date_format(o.inbound_date, '%Y%m%d') >= date_format(#{params.beginTime}, '%Y%m%d')
    and date_format(o.inbound_date, '%Y%m%d') <= date_format(#{params.endTime}, '%Y%m%d')

order by o.inbound_date desc, o.inbound_order_id desc
